local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'

local UIModule = CS.Engine.UI.UIModule
local UITaskCellPath = "Game.Activity.JapaneseStory.JapaneseRewardDialogCell"
local CDTimerModule = CS.Engine.Modules.CDTimerModule

--- from: Assets/BundleResources/Prefabs/ActivityJapaneseLevel/Story/ActivityJapaneseRewardDialog.prefab > name: ActivityJapaneseRewardDialog
---@class JapaneseRewardDialog
---@field Env                           	JapaneseRewardDialog                    
---@field controller                    	Engine.UI.UILuaDialog                   
---@field Text2                         	UnityEngine.RectTransform               	@ 0    
