local JapaneseRewardDialog = Class("JapaneseRewardDialog")

---@type JapaneseStoryMgr
local JapaneseStoryMgr = import("Game.Activity.JapaneseStory.JapaneseStoryMgr"):GetInstance()
---@type JapaneseStoryUtils
local JapaneseStoryUtils = import("Game.Activity.JapaneseStory.JapaneseStoryUtils")
function JapaneseRewardDialog:__init()
	self._activityUuid = 0
	self._activityId = 0               --当前活动id
	self._allReward = {}            --所有的奖励
end

function JapaneseRewardDialog:__delete()
	self._activityUuid = nil
	self._activityId = nil
	self._allReward = nil
end

function JapaneseRewardDialog:Awake()
	GameUtils.RefreshTopGoods(Constants.UITypeIds.ActivityJapaneseRewardDialog)
	self.activityDojo = JapaneseStoryMgr:GetActivityDojo()
	self._activityId = JapaneseStoryMgr:GetActivityId()    --活动id
	if self._activityId == 0 then
		return
	end
	local vo = JapaneseStoryMgr:GetScheduleVo()
	CfUtils.FillImage(self.ImgBg, vo.storeSceneId)
	
	if not isNull(self._timeDown) then
		CDTimerModule.GetInstance():RemoveCD(self._timeDown)
		self._timeDown = nil
	end
	self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
		self:FillTime()
	end, 2592000, false, true)
end

function JapaneseRewardDialog:FillTime()
	local serverTime = GameUtils.GetServerTime()
	local num = checkNumber(self.activityDojo.closeTime) - checkNumber(serverTime)
	if num < 0 then
		num = 0
	end
	CfUtils.FillText(self.Text2, CfUtils.GetTimeHMS4(num))
end

function JapaneseRewardDialog:RefreshShow()
	GameUtils.Request(Interfaces.JapaneseStoryTask, {activityUuid = self._activityId, type = JapaneseStoryUtils.TaskType.Achievement}, Bind(self, self.TaskHomeResponseHandler))
end

function JapaneseRewardDialog:TaskHomeResponseHandler(request, response)
	if checkInt(response.errCode) == 0 then
		self.taskData = response.data.tasks
		self.maxData = self.taskData[#self.taskData]
		table.remove(self.taskData,#self.taskData)
		table.sort(self.taskData, function(a, b)
			local aStatus = checkInt(a.status)
			local bStatus = checkInt(b.status)
			if aStatus == bStatus then
				return checkInt(a.id) < checkInt(b.id)
			else
				if aStatus == 1 then
					return true
				elseif bStatus == 1 then
					return false
				elseif aStatus == 2 then
					return false
				elseif bStatus == 2 then
					return true
				else
					return false
				end
			end
		end)
		self:FillSelf()
	end
end

function JapaneseRewardDialog:FillSelf()
	local vo = JapaneseStoryMgr:GetScheduleVo()
	if not vo then
		return
	end
	
	self:RefreshScoreShow(vo)
	
	self:FillTime()
	
	self:FillCellShow()
	
	local scr = CfUtils.GetLuaScr(self.BtnRoleNameNode, "Game.UI.Common.CommonBtnRoleNameNode")
	if scr then
		scr:RefreshSelf(vo.cardId, nil, function(cardId)
			local GachaponUtils = import('Game.Gachapon.GachaponUtils')
			GachaponUtils.OpenDetail(cardId, { { id = Constants.UITypeIds.ActivityJapaneseRewardDialog } })
		end)
	end
	
	vo = CardConfMgr:GetInstance():GetCardByRefId(vo.cardId)
	self.BossDrawingNode:Execute(checkNumber(vo.defaultSkin))
	
	self.TaskList:InitListView(table.count(self.taskData), Bind(self, self.OnGetItemByIndex))
	
	SetButtonAction(self.FontStyleButton, Bind(self, self.OneKeyReward))
end

function JapaneseRewardDialog:FillCellShow()
	local count = #self.taskData
	local data = self.maxData
	local env = CfUtils.GetLuaScr(self.ResidentCell, UITaskCellPath)
	if isNotNull(env) then
		env:Refresh(data, Bind(self,self.OnMaxTaskCellClick), count)
	end
	CfUtils.SetActive(self.ResidentCell.gameObject, true)
end

function JapaneseRewardDialog:RefreshScoreShow(vo)
	local node = CfUtils.GetLuaScr(self.ImgIcon,"Game.Behaviours.CommonCurrencyNode")
	if isNotNull(node) then
		node:SetCurrencyShow(vo.currencyId, GoodsUtils.GetThingNo(vo.currencyId))
	end
end

function JapaneseRewardDialog:OneKeyReward()
	local isHaveReward = self:IsHaveTaskReward()
	if isHaveReward then
		local activityId = JapaneseStoryMgr:GetActivityId()
		local data = {activityUuid = activityId, taskId = 0, type = JapaneseStoryUtils.TaskType.Achievement}
		GameUtils.Request(Interfaces.JapaneseStoryDrawTask, data,function(request,response)
			if checkNumber(response.errCode) ~= 0 then return end
			local jsonData = response.data
			local rewards = checkTable(jsonData.rewards)
			if #rewards > 0 then
				GoodsUtils.DrawRewards(rewards)
				UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
			end
			self:RefreshTaskShow()
		end)
	else
		GameUtils.Toast(localize("暂无可领取的奖励"))
	end
end

function JapaneseRewardDialog:RefreshTaskShow()
	for i, v in ipairs(self.taskData) do
		if v.status == 1 then
			v.status = 2
		end
	end
	
	if self.maxData.status == 1  then
		self.maxData.status = 2
	end
	
	local vo = JapaneseStoryMgr:GetScheduleVo()
	self:RefreshScoreShow(vo)
	GameUtils.ReloadData(self.TaskList, table.count(self.taskData))
	self:FillCellShow()
	self:UpdateRedPoint()
end

function JapaneseRewardDialog:IsHaveTaskReward()
	for i, v in ipairs(self.taskData) do
		if v.status == 1 then
			return true
		end
	end
	
	if self.maxData.status == 1 then
		return true
	end
	return false
end

function JapaneseRewardDialog:OnGetItemByIndex(listView, index)
	if index < 0 then
		return
	end
	local cell = listView:NewListViewItem("Cell")
	local scr = CfUtils.GetLuaScr(cell.gameObject, UITaskCellPath)
	local data = self.taskData[index + 1]
	if scr then
		scr:Refresh(data, Bind(self,self.OnTaskCellClick),index + 1)
	end
	
	return cell
end

function JapaneseRewardDialog:OnTaskCellClick(index)
	local data = self.taskData[index]
	if data.status == 2 then
		GameUtils.Toast(localize("奖励已领取"))
		return
	end
	if data.status == 1 then
		local activityId = JapaneseStoryMgr:GetActivityId()
		local serverData = {activityUuid = activityId, taskId = data.id, type = JapaneseStoryUtils.TaskType.Achievement}
		GameUtils.Request(Interfaces.JapaneseStoryDrawTask, serverData,function(request,response)
			if checkNumber(response.errCode) ~= 0 then return end
			local jsonData = response.data
			data.status = 2
			local rewards = checkTable(jsonData.rewards)
			if #rewards > 0 then
				GoodsUtils.DrawRewards(rewards)
				UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
			end
			local vo = JapaneseStoryMgr:GetScheduleVo()
			self:RefreshScoreShow(vo)
			GameUtils.ReloadData(self.TaskList, table.count(self.taskData))
			self:FillCellShow()
			self:UpdateRedPoint()
		end)
	else
		GameUtils.Toast(localize("未达成领取条件"))
	end
end

function JapaneseRewardDialog:OnMaxTaskCellClick()
	local data = self.maxData
	if data.status == 2 then
		GameUtils.Toast(localize("奖励已领取"))
		return
	end
	if data.status == 1 then
		local activityId = JapaneseStoryMgr:GetActivityId()
		local serverData = {activityUuid = activityId, taskId = data.id, type = JapaneseStoryUtils.TaskType.Achievement}
		GameUtils.Request(Interfaces.JapaneseStoryDrawTask, serverData,function(request,response)
			if checkNumber(response.errCode) ~= 0 then return end
			local jsonData = response.data
			data.status = 2
			local rewards = checkTable(jsonData.rewards)
			if #rewards > 0 then
				GoodsUtils.DrawRewards(rewards)
				UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
			end
			local vo = JapaneseStoryMgr:GetScheduleVo()
			self:RefreshScoreShow(vo)
			self:FillCellShow()
			self:UpdateRedPoint()
		end)
	else
		GameUtils.Toast(localize("未达成领取条件"))
	end
end

function JapaneseRewardDialog:UpdateRedPoint()
	local taskTips = -1
	for i, v in ipairs(self.taskData) do
		if v.status == 1 then
			taskTips = 0
			break
		end
	end
	JapaneseStoryMgr:SetAchievementTaskTips(taskTips)
end

function JapaneseRewardDialog:OnInitialize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		self:RefreshShow()
	end))
	return coWait
end

function JapaneseRewardDialog:OnFinalize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		if not isNull(self._timeDown) then
			CDTimerModule.GetInstance():RemoveCD(self._timeDown)
			self._timeDown = nil
		end
		
		self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
		self:Delete()
		self = nil --lua层的gc需要
	end))
	return coWait
end


return JapaneseRewardDialog